    long long n;
    long long k;
    cin >> n >> k;
    vector<long long> a(n);
    for (int i = 0; i < n; i++) cin >> a[i];

    int l = 0, best = 0;
    long long total = 0;
    for (int rr = 0; rr < n; rr++) {
        total += a[rr];
        while (total > k) {
            total -= a[l];
            l++;
